{
  "case_id": "xsu_sg_004_multiple_impairments",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret stemmer med rubrikken og kilderne: samlet vurdering ved flere ansøgte funktionsnedsættelser, udgangspunkt om kun de angivne, journalomtale inddrages ikke automatisk, og senere inddragelse kræver ønske og tilstrækkelig dokumentation. Ingen væsentlig juridisk fejl."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fire kritiske elementer er med. Samlet vurdering er nævnt. Ansøgeren skal oplyse om og dokumentere funktionsnedsættelserne. Udgangspunktet er de ansøgte. Senere inddragelse sker efter anmodning og med tilstrækkelig dokumentation. Svaret siger ikke udtrykkeligt, at dokumentationen skal opfylde minimumskravene, men 'tilstrækkelig dokumentation' er en acceptabel gengivelse."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvilke funktionsnedsættelser Udbetaling Danmark vurderer, uden irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken bestemmelse, vejledningsafsnit eller lovtekst. Udsagnene er ikke tilskrevet nogen kilde."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle væsentlige regler i svaret har støtte i vejledningens afsnit 3.4.1.2 og 3.5 og i SU-bekendtgørelsens § 37. Svaret tilføjer ingen ny regel eller betingelse."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bevarer 'som udgangspunkt', at journalomtale ikke automatisk inddrages, og betingelserne for senere inddragelse: ansøgerens anmodning og tilstrækkelig dokumentation. At funktionsnedsættelsen skal være varig er nævnt for udgangspunktet. Det er ikke gentaget for den senere tilføjelse, men det er ikke afgørende."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Trinnene er sammenhængende: samlet vurdering af de ansøgte, journalomtale alene udvider ikke, og udvidelse sker på ansøgerens anmodning med dokumentation. Konklusionen følger af dem."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Som udgangspunkt', 'skal oplyse', 'inddrages ikke automatisk' og 'kan bede om' gengiver kilderne præcist. Svaret gør ikke udgangspunktet eller skønnet absolut."
    }
  },
  "xhaile_coverage": {
    "A16": {
      "label": "yes",
      "reason": "Svaret angiver, at Udbetaling Danmark foretager en samlet vurdering ved flere funktionsnedsættelser, og at ansøgeren skal oplyse om dem og indsende dokumentation for hver."
    },
    "A24": {
      "label": "yes",
      "reason": "Svaret angiver, at kun de funktionsnedsættelser, der specifikt er angivet i ansøgningen, vurderes som udgangspunkt, og at journalomtale af andre ikke automatisk inddrages."
    },
    "A25": {
      "label": "partial",
      "reason": "Svaret dækker, at ansøgeren under sagen kan bede om yderligere inddragelse med tilstrækkelig dokumentation. Det nævner ikke udtrykkeligt, at nedsættelsen skal være varig, at minimumskravene til dokumentation skal være opfyldt, eller at det alene sker på ansøgerens initiativ."
    }
  },
  "overall_notes": "Indholdsmæssigt korrekt og næsten fuldstændigt svar, men uden kildeangivelse. Derfor C04 not_met og C05 og C06 not_assessable. Kravet om varighed og minimumskravene til dokumentation for senere tilføjelser er kun delvist udtrykt."
}

